-- Robert Ramirez (profileID=18) — ENDORSEMENTS
-- Generated by endorsement_framework.py

-- STEP 1: PHRASE_ENDORSE rows for all Robert Ramirez phrasings

SELECT p.argumentID, p.phrasingID, 18, 100, 1
FROM PHRASING p
WHERE p.coinedBy = 18
  AND NOT EXISTS (
    SELECT 1 FROM PHRASE_ENDORSE pe
    WHERE pe.profileID = 18 AND pe.argumentID = p.argumentID
  );

-- STEP 2: Endorsement chains (Because / Therefore / Rebuttal)

DELETE FROM ENDORSEMENT WHERE profileID=18 AND targArgID IN (80,88,89,90,94,96,104,107,110,120,121,123,124,125,130,134,135,136,140,141,145,161,226,230,288,297,315,321,326,327,328,349,400,401,404,405,407,414,428,460,461,476,543,547,548,549,554,555,560,561,567,568,602,606,609,611,612,615,616,618,651,652,658,659,729,743,746,747,777,844,849,902,1027,1028,1237,1275,1276,1385,1386,1387,1410,1411,1440);


-- STEP 3: Sync PHRASE_ENDORSE active flag with opinion acceptance

UPDATE PHRASE_ENDORSE pe
JOIN OPINION o ON pe.argumentID = o.argumentID AND o.profileID = 18
SET pe.active = o.acceptance
WHERE pe.profileID = 18;

SELECT 'Done: endorsements for profileID=18' AS status;